import React, { useState, useEffect } from 'react';
import { StyleSheet, Text, View, TextInput, TouchableOpacity, Alert, KeyboardAvoidingView, Platform, ScrollView, Image, Modal, Animated, Easing } from 'react-native';
import { useRouter } from 'expo-router';
import { StatusBar } from 'expo-status-bar';
import { Ionicons } from '@expo/vector-icons';
import axios from 'axios';
import { API_URL, setApiUrl, cargarApiUrl } from '../constants';


const LOGO_URI = "data:image/png;base64,"; // (base64 sin cambios)

export default function LoginScreen() {
  const [usuario, setUsuario] = useState('');
  const [clave, setClave] = useState('');
  const [mostrarClave, setMostrarClave] = useState(false);
  const [errorUsuario, setErrorUsuario] = useState('');
  const [errorClave, setErrorClave] = useState('');
  const [contadorClics, setContadorClics] = useState(0);
  const [intentosFallidos, setIntentosFallidos] = useState(0);
  const [bloqueado, setBloqueado] = useState(false);
  const [modalVisible, setModalVisible] = useState(false);
  const [nuevaIp, setNuevaIp] = useState('');
  // Modo Dios
  const [modoDiosVisible, setModoDiosVisible] = useState(false);
  const matrixAnim = useState(new Animated.Value(0))[0];
  const glowAnim = useState(new Animated.Value(0))[0];
  const scaleAnim = useState(new Animated.Value(0.5))[0];

  useEffect(() => {
    cargarApiUrl();
  }, []);

  const activarMenuSecreto = () => {
    const nuevoConteo = contadorClics + 1;
    if (nuevoConteo >= 10) {
      setContadorClics(0);
      // Activar Modo Dios
      setModoDiosVisible(true);
      matrixAnim.setValue(0);
      glowAnim.setValue(0);
      scaleAnim.setValue(0.5);
      Animated.parallel([
        Animated.timing(matrixAnim, {
          toValue: 1,
          duration: 600,
          easing: Easing.out(Easing.cubic),
          useNativeDriver: true,
        }),
        Animated.spring(scaleAnim, {
          toValue: 1,
          friction: 4,
          tension: 40,
          useNativeDriver: true,
        }),
        Animated.loop(
          Animated.sequence([
            Animated.timing(glowAnim, { toValue: 1, duration: 900, useNativeDriver: true }),
            Animated.timing(glowAnim, { toValue: 0.3, duration: 900, useNativeDriver: true }),
          ])
        ),
      ]).start();
    } else {
      setContadorClics(nuevoConteo);
    }
  };

  const cerrarModoDios = () => {
    Animated.timing(matrixAnim, {
      toValue: 0,
      duration: 400,
      useNativeDriver: true,
    }).start(() => {
      setModoDiosVisible(false);
      glowAnim.stopAnimation();
    });
  };

  const confirmarCambioIp = async () => {
    if (nuevaIp.trim()) {
      await setApiUrl(nuevaIp.trim());
      setModalVisible(false);
      Alert.alert('Listo', 'Ahora la App usará la IP: ' + nuevaIp.trim());
    }
  };

  const router = useRouter();

  const MAX_INTENTOS = 5;

  // Desbloquear el botón cuando el usuario cierra el error y edita los campos
  const desbloquear = () => {
    if (bloqueado) {
      setBloqueado(false);
      setIntentosFallidos(0);
      setErrorUsuario('');
      setErrorClave('');
    }
  };

  const manejarLogin = async () => {
    if (bloqueado) {
      Alert.alert(
        'Acceso bloqueado',
        'Se superaron los intentos permitidos. Toca "Reintentar" para desbloquear el formulario.',
        [
          { text: 'Reintentar', onPress: desbloquear },
          { text: 'Cancelar', style: 'cancel' },
        ]
      );
      return;
    }

    setErrorUsuario('');
    setErrorClave('');

    if (!usuario.trim()) { setErrorUsuario('Ingresa tu usuario'); return; }
    if (!clave.trim()) { setErrorClave('Ingresa tu contraseña'); return; }
    if (clave.trim().length < 4) { setErrorClave('La contraseña debe tener mínimo 4 caracteres'); return; }
    // HINT visible: el límite de 8 caracteres se informa antes de intentar
    if (clave.trim().length > 8) { setErrorClave('La contraseña no puede tener más de 8 caracteres'); return; }

    try {
      await cargarApiUrl();
      const res = await axios.post(`${API_URL}/login`, { usuario: usuario.trim(), contrasena: clave.trim() });

      if (res.data.success) {
        setIntentosFallidos(0);
        router.replace({
          pathname: '/ano',
          params: {
            rol: res.data.rol,
            usuario: res.data.usuario,
            menciones_permitidas: res.data.menciones_permitidas || '',
            materia: res.data.materia || ''
          }
        });
      } else {
        const nuevosIntentos = intentosFallidos + 1;
        setIntentosFallidos(nuevosIntentos);
        if (nuevosIntentos >= MAX_INTENTOS) {
          setBloqueado(true);
          setErrorUsuario('Demasiados intentos fallidos. Toca el botón bloqueado para reintentar.');
        } else if (res.data.campo === 'usuario') {
          setErrorUsuario(`El usuario no existe (intento ${nuevosIntentos}/${MAX_INTENTOS})`);
        } else if (res.data.campo === 'contrasena') {
          setErrorClave(`Contraseña incorrecta (intento ${nuevosIntentos}/${MAX_INTENTOS})`);
        } else {
          setErrorUsuario(`Error al iniciar sesión (intento ${nuevosIntentos}/${MAX_INTENTOS})`);
        }
      }
    } catch (e) {
      Alert.alert(
        'Sin conexión',
        'No se pudo conectar con el servidor.\nVerifica tu conexión a internet o que el servidor esté encendido.',
        [{ text: 'Entendido' }]
      );
    }
  };

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      style={styles.container}
    >
      <StatusBar style="light" />
      <ScrollView contentContainerStyle={styles.scrollContainer}>

        <View style={styles.loginCard}>
          <View style={styles.header}>
            <TouchableOpacity
              onPress={activarMenuSecreto}
              activeOpacity={1}
              style={{ zIndex: 999 }}
            >
              <View style={styles.iconBox}>
                <Image
                  source={{ uri: LOGO_URI }}
                  style={styles.logoImg}
                  resizeMode="contain"
                />
              </View>
            </TouchableOpacity>
            <Text style={styles.logoText}>E.T. J.R.G.S</Text>
            <Text style={styles.titulo}>Control de Asistencia</Text>
          </View>

          <View style={styles.form}>
            {/* Input Usuario */}
            <View style={styles.inputContainer}>
              <Text style={styles.label}>Usuario</Text>
              <View style={[styles.inputWrapper, errorUsuario ? styles.inputWrapperError : null]}>
                <Ionicons name="person-outline" size={20} color={errorUsuario ? '#EF4444' : '#2B5280'} style={{ marginRight: 10 }} />
                <TextInput
                  style={styles.input}
                  placeholder="Ingresa tu usuario"
                  placeholderTextColor="#94A3B8"
                  value={usuario}
                  onChangeText={(t) => { setUsuario(t); setErrorUsuario(''); }}
                  autoCapitalize="none"
                />
              </View>
              {errorUsuario ? (
                <View style={styles.errorRow}>
                  <Ionicons name="alert-circle-outline" size={14} color="#EF4444" />
                  <Text style={styles.errorText}>{errorUsuario}</Text>
                </View>
              ) : null}
            </View>

            {/* Input Contraseña */}
            <View style={styles.inputContainer}>
              <Text style={styles.label}>Contraseña</Text>
              <View style={[styles.inputWrapper, errorClave ? styles.inputWrapperError : null]}>
                <Ionicons name="lock-closed-outline" size={20} color={errorClave ? '#EF4444' : '#2B5280'} style={{ marginRight: 10 }} />
                <TextInput
                  style={styles.input}
                  placeholder="••••••••"
                  placeholderTextColor="#94A3B8"
                  value={clave}
                  onChangeText={(t) => { setClave(t); setErrorClave(''); }}
                  secureTextEntry={!mostrarClave}
                  autoCorrect={false}
                  autoComplete="off"
                />
                <TouchableOpacity onPress={() => setMostrarClave(!mostrarClave)}>
                  <Ionicons
                    name={mostrarClave ? "eye-off-outline" : "eye-outline"}
                    size={22}
                    color="#003399"
                  />
                </TouchableOpacity>
              </View>
              {errorClave ? (
                <View style={styles.errorRow}>
                  <Ionicons name="alert-circle-outline" size={14} color="#EF4444" />
                  <Text style={styles.errorText}>{errorClave}</Text>
                </View>
              ) : (
                <View style={styles.hintRow}>
                  <Ionicons name="information-circle-outline" size={13} color="#8A9BB0" />
                  <Text style={styles.hintText}>Entre 4 y 8 caracteres</Text>
                </View>
              )}
            </View>

            <TouchableOpacity
              style={[styles.boton, bloqueado && styles.botonBloqueado]}
              onPress={manejarLogin}
            >
              <Text style={styles.botonText}>{bloqueado ? 'BLOQUEADO — Toca para reintentar' : 'ACCEDER AL SISTEMA'}</Text>
              <Ionicons name={bloqueado ? "lock-closed" : "chevron-forward"} size={20} color="#020617" />
            </TouchableOpacity>
          </View>
        </View>

        <View style={styles.footer}>
          <Text style={styles.footerText}>Telemática 2027</Text>
        </View>

      </ScrollView>

      <Modal
        visible={modalVisible}
        transparent
        animationType="fade"
        onRequestClose={() => setModalVisible(false)}
      >
        <View style={styles.modalOverlay}>
          <View style={styles.modalBox}>
            <Text style={styles.modalTitulo}>Configuración del Servidor</Text>
            <Text style={styles.modalSubtitulo}>Introduce la nueva IP (ej: 192.168.1.50)</Text>
            <TextInput
              style={styles.modalInput}
              value={nuevaIp}
              onChangeText={setNuevaIp}
              placeholder="192.168.1.50"
              placeholderTextColor="#94A3B8"
              keyboardType="default"
              autoCapitalize="none"
              autoCorrect={false}
            />
            <View style={styles.modalBotones}>
              <TouchableOpacity
                style={[styles.modalBoton, styles.modalBotonCancelar]}
                onPress={() => setModalVisible(false)}
              >
                <Text style={styles.modalBotonTextoCancelar}>Cancelar</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[styles.modalBoton, styles.modalBotonConfirmar]}
                onPress={confirmarCambioIp}
              >
                <Text style={styles.modalBotonTextoConfirmar}>Cambiar IP</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>

      {/* ══════════════════════════════════════════
          MODO DIOS 🔱 — Easter egg secreto
          Se activa con 10 toques en el logo.
          Pantalla Matrix animada, solo visual.
      ══════════════════════════════════════════ */}
      <Modal
        visible={modoDiosVisible}
        transparent
        animationType="none"
        onRequestClose={cerrarModoDios}
      >
        <Animated.View
          style={[
            styles.modoDiosOverlay,
            { opacity: matrixAnim },
          ]}
        >
          {/* Lluvia de caracteres Matrix — decorativa */}
          <View style={styles.matrixRain} pointerEvents="none">
            {[...Array(18)].map((_, i) => (
              <Animated.Text
                key={i}
                style={[
                  styles.matrixCol,
                  {
                    left: `${(i * 5.5) + 1}%`,
                    opacity: glowAnim.interpolate({
                      inputRange: [0.3, 1],
                      outputRange: [0.15 + (i % 5) * 0.07, 0.6 + (i % 3) * 0.1],
                    }),
                    transform: [{
                      translateY: matrixAnim.interpolate({
                        inputRange: [0, 1],
                        outputRange: [-80 - i * 12, 0],
                      }),
                    }],
                  },
                ]}
              >
                {['01', '10', '11', '00', '1', '0', 'δ', 'λ', 'Ω', '∑', '█', '▓'][i % 12]}
                {'\n'}
                {['10', '01', '0', '1', '11', '∫', 'π', '∞', '▒', '░', '01', '10'][i % 12]}
                {'\n'}
                {['1', '0', '11', '10', '01', 'σ', 'μ', 'ψ', '█', '▓', '0', '1'][i % 12]}
              </Animated.Text>
            ))}
          </View>

          {/* Tarjeta central */}
          <Animated.View
            style={[
              styles.modoDiosCard,
              {
                transform: [{ scale: scaleAnim }],
                opacity: matrixAnim,
              },
            ]}
          >
            <Animated.Text
              style={[
                styles.modoDiosTridente,
                {
                  opacity: glowAnim,
                  transform: [{
                    scale: glowAnim.interpolate({
                      inputRange: [0.3, 1],
                      outputRange: [0.95, 1.08],
                    }),
                  }],
                },
              ]}
            >
              🔱
            </Animated.Text>

            <Text style={styles.modoDiosTitulo}>MODO DIOS</Text>
            <Text style={styles.modoDiosSubtitulo}>Acceso de nivel supremo concedido</Text>

            <View style={styles.modoDiosSeparador} />

            <Text style={styles.modoDiosMensaje}>
              "Tú construiste esto."
            </Text>

            <View style={styles.modoDiosBadge}>
              <Text style={styles.modoDiosBadgeText}>⚡ DEV: JRGS · Sistema v1.0</Text>
            </View>

            <View style={styles.modoDiosBadge2}>
              <Text style={styles.modoDiosBadgeText2}>📅 E.T. J.R.G.S — Telemática 2027</Text>
            </View>

            <TouchableOpacity
              style={styles.modoDiosBoton}
              onPress={cerrarModoDios}
              activeOpacity={0.8}
            >
              <Text style={styles.modoDiosBotonText}>[ SALIR DEL MODO DIOS ]</Text>
            </TouchableOpacity>
          </Animated.View>
        </Animated.View>
      </Modal>

    </KeyboardAvoidingView>
  );
}

